\label{thm:gkz}
Let $A\in\mathbb Z^{d\times n}$ be an integer matrix of rank $d$ with nonzero columns, and assume that $\mathbb N A$ is pointed. Let $L=(u,v)\in\mathbb Q^{2n}$ be a projective weight. For every $\tau\in\Phi_A^L$ and every integer $r$, the set
\[
\{\beta\in\mathbb C^d:\mu_{A,0}^{L,\tau}(\beta)\ge r\}
\]
is Zariski closed.

\label{def:projective-filtration}
A rational weight $L=(u,v)\in\mathbb Q^{2n}$ is \emph{projective} if $u_j+v_j=c>0$ for every $j$. The associated filtration on $D_B$ is
\begin{equation}\label{eq:filtration-D}
F_k^LD_B=\sum_{u\cdot\alpha+v\cdot\gamma\le k}B x^\alpha\partial^\gamma.
\end{equation}

\label{def:characteristic-cycle}
Let $N$ be a finite $D$-module with a good $L$-filtration $F$. Its \emph{$L$-characteristic variety} is $\operatorname{Ch}^L(N)=\operatorname{Supp}\operatorname{gr}_FN$. When this support is contained in a finite union of distinct irreducible subvarieties $\Lambda_i$ of dimension $n$, its \emph{$L$-characteristic cycle} is
\begin{equation}\label{eq:cc-length}
\operatorname{CC}^L(N)=\sum_i\ell_{W_{P_i}}(\operatorname{gr}_FN)_{P_i}[\Lambda_i],
\quad P_i=I(\Lambda_i).
\end{equation}
Here $\ell$ denotes module length, and a component that does not occur is assigned coefficient zero.

\label{lem:basechange}
Let $B\to B'$ be a homomorphism of Noetherian commutative $\mathbb C$-algebras, and let $M$ be a finite $D_B$-module with a good filtration $F$. Equip $M'=M\otimes_BB'$ with the filtration
\[
F_kM'=\operatorname{im}(F_kM\otimes_BB'\longrightarrow M').
\]
Then this filtration is good, and there is a natural surjection
\begin{equation}\label{eq:basechange-surj}
(\operatorname{gr}_FM)\otimes_BB'\longrightarrow\operatorname{gr}_FM'.
\end{equation}
More precisely, if $N=\mathscr M\otimes_BB'$, then
\begin{equation}\label{eq:basechange-rees}
\operatorname{Rees}_FM'=N/H^0_{(h)}N.
\end{equation}
If $B'$ is flat over $B$, the map in \eqref{eq:basechange-surj} is an isomorphism.

\label{def:relative-support}
A finite $D_B$-module $M$ with a good filtration $F$ satisfies the \emph{product support condition} for $\Lambda$ if
\begin{equation}\label{eq:product-support}
\operatorname{Supp}\operatorname{gr}_FM\subseteq\Lambda\times\operatorname{Spec} B.
\end{equation}
For such a module and a closed point $b\in\operatorname{Spec} B$, its fiber multiplicities are
\begin{equation}\label{eq:mu-family}
\mu_i(M_b)=\ell_{W_{P_i}}(\operatorname{gr}_FM_b)_{P_i}.
\end{equation}
Here $M_b=M\otimes_B\kappa(b)$ has the induced filtration of Lemma~\ref{lem:basechange}. For an integral parameter ring with fraction field $K$, the generic multiplicities $\mu_i(M_K)$ are defined using the corresponding primes $P_iW_K$. The specialization homomorphism $\operatorname{sp}_\Lambda$ is defined by $\operatorname{sp}_\Lambda[\Lambda_i\times\operatorname{Spec} K]=[\Lambda_i]$.

\label{thm:curve}
Let $M$ be a finite $D_R$-module with a good $L$-filtration satisfying the product support condition \eqref{eq:product-support}. If $T=H^0_{(t)}M$, then
\begin{equation}\label{eq:curve-tor}
\operatorname{CC}^L(M/tM)-\operatorname{sp}_\Lambda\operatorname{CC}^L(M_K)=\operatorname{CC}^L(T/tT)=\operatorname{CC}^L\bigl(\operatorname{Tor}_1^R(M,k)\bigr).
\end{equation}
Consequently, $\mu_i(M/tM)\ge\mu_i(M_K)$ for every $i$.

\label{lem:nilpotent}
Let $\mathscr A$ be a left Noetherian ring, let $z\in\mathscr A$ be central, and let $V$ be a finite $\mathscr A$-module such that $z^aV=0$ for some $a\ge1$. In the Grothendieck group of finite $\mathscr A/(z)$-modules,
\begin{equation}\label{eq:nilpotent-class}
[V/zV]=[0:_Vz].
\end{equation}
The same identity holds for any additive invariant defined on the modules appearing in the proof.

\label{lem:two-parameters}
Let $t,h$ be central elements of a left Noetherian ring $\mathscr A$, and let $\mathscr Q$ be a finite $\mathscr A$-module on which multiplication by $t$ and multiplication by $h$ are injective. Set
\[
G=\mathscr Q/h\mathscr Q,
\quad N=\mathscr Q/t\mathscr Q,
\quad U=H^0_{(h)}N,
\quad V=N/U.
\]
Then $U$ is annihilated by a power of $h$, $V$ is $h$-torsion-free, and
\begin{equation}\label{eq:two-exact}
0\longrightarrow U/hU\longrightarrow G/tG\longrightarrow V/hV\longrightarrow0
\end{equation}
is exact. There is a natural isomorphism, up to a grading shift,
\begin{equation}\label{eq:two-kernels}
0:_Nh\simeq0:_Gt.
\end{equation}
In the Grothendieck group of finite $\mathscr A/(t,h)$-modules,
\begin{equation}\label{eq:two-class}
[V/hV]=[G/tG]-[0:_Gt].
\end{equation}

\label{prop:torsionfree-constant}
If $Q$ has no $R$-torsion and satisfies \eqref{eq:product-support}, then
\begin{equation}\label{eq:torsionfree-cycle}
\operatorname{CC}^L(Q/tQ)=\operatorname{sp}_\Lambda\operatorname{CC}^L(Q_K).
\end{equation}

\label{prop:dense-open}
Assume that $B$ is a domain, with fraction field $K$. There is a nonzero $f\in B$ such that, for every closed point $b\in\operatorname{Spec} B_f$ and every $i$,
\begin{equation}\label{eq:dense-open-constant}
\mu_i(M_b)=\mu_i(M_K).
\end{equation}

\label{def:orbit-conormal}
For a subset $\tau$ of the column indices, let $\mathbf1_\tau$ have coordinate one on $\tau$ and zero elsewhere, and let $O_A^\tau=T_A\cdot\mathbf1_\tau$. In the cotangent coordinates $(x,\xi)$ used in \cite{SW08}, define
\begin{equation}\label{eq:conormal-orbit}
C_A^\tau=\{(x,\xi):\xi\in O_A^\tau,\ \textstyle\sum_j a_{ij}x_j\xi_j=0\text{ for }1\le i\le d\},
\quad \Lambda_\tau=\overline{C_A^\tau}.
\end{equation}

\label{cor:gkz-curve}
Let an irreducible algebraic curve map to $\mathbb C^d$, and let $R$ be the local ring at a closed point of its normalization, with fraction field $K$ and residue field $k=\mathbb C$. Write $\beta_0$ and $\beta_\eta$ for the special and generic parameters. For $\mathcal M_R=\mathcal M_B\otimes_BR$,
\begin{equation}\label{eq:gkz-tor-difference}
\mu_{A,0}^{L,\tau}(\beta_0)-\mu_{A,0}^{L,\tau}(\beta_\eta)
=\mu^{L,\Lambda_\tau}\bigl(\operatorname{Tor}_1^R(\mathcal M_R,k)\bigr)\ge0.
\end{equation}
Here the generic multiplicity is computed over $K$, and $\mu^{L,\Lambda_\tau}$ denotes the coefficient at $\Lambda_\tau$.

\label{cor:gkz-loci}
For fixed $A$ and $L$, the vector $(\mu_{A,0}^{L,\tau}(\beta))_{\tau\in\Phi_A^L}$ takes finitely many values. If $\mu_A^{L,\tau}$ denotes its generic coefficient at $\Lambda_\tau$, then
\[
\mathcal E_A^{L,\tau}=\{\beta:\mu_{A,0}^{L,\tau}(\beta)>\mu_A^{L,\tau}\}
\]
is a proper Zariski closed subset of $\mathbb C^d$.

\label{ex:rankjump-seed}
Let
\[
T_0=\begin{pmatrix}1&1&1&1\\0&1&3&4\end{pmatrix},
\quad b=(1,2).
\]
This is the classical rank-jump configuration of Sturmfels--Takayama \cite{ST98}, also used in \cite{MMW05,BFF20}. Its saturated semigroup consists of $(k,j)$ with $k\ge0$ and $0\le j\le4k$. The only missing degree is $b$: sums of two elements of $\{0,1,3,4\}$ fill $\{0,\ldots,8\}$, and adding zero or four proves the assertion at every subsequent level. Hence
\begin{equation}\label{eq:normalization-T}
\widetilde S_{T_0}/S_{T_0}\simeq\mathbb C(b),
\end{equation}
where every positive-degree semigroup generator annihilates $\mathbb C(b)$. Its Euler--Koszul homology in degree $j$ is $\mathbb C[x]\otimes\bigwedge^j\mathbb C^2$ at $\beta_T=b$ and vanishes at all other parameters. The normalization is Cohen--Macaulay by \cite{Hoc72}. Its zero-section coefficient is four for every projective weight: the columns of $T_0$ are homogeneous, and the corresponding triangles in the umbrella have total normalized area four. The long exact sequence in Euler--Koszul homology therefore gives
\begin{equation}\label{eq:muT}
\mu_{T_0,0}^{L,\varnothing}(\beta_T)=4+\mathbf 1_{\{b\}}(\beta_T).
\end{equation}
The correction at $b$ is $2-1=1$.

\label{lem:index}
Let $N$ be holonomic. Assume that its algebraic slopes along $Y$ belong to a finite set $\Sigma\subset\mathbb Q_{>1}$ and that its $L(r)$-characteristic varieties are $(F,V_Y)$-bihomogeneous for $r\notin\Sigma$. Choose rational $r_0>1$ before every member of $\Sigma$, and rational $r_+>s$ so that no member of $\Sigma$ is in $(s,r_+]$. Then
\begin{equation}\label{eq:G}
d_s(N)=\phi_{r_+}(N)-\phi_{r_0}(N).
\end{equation}
For non-slope levels $1<a<b$, the dimensions in Definition~\ref{def:gevrey-graded} satisfy
\begin{equation}\label{eq:grade}
e_{a,b}(N)=d_b(N)-d_a(N)\geq0.
\end{equation}

\label{thm:gevrey-general}
Under \eqref{eq:gevrey-support} and \eqref{eq:gevrey-bihom}, $d_s(M_b)$ and each individual generic Gevrey graded dimension are Zariski upper semicontinuous. More precisely, on every parameter curve,
\begin{align}
 d_s(M_0)-d_s(M_{\mathrm{gen}})&=d_s(T),\label{eq:Gtor}\\
 e_\rho(M_0)-e_\rho(M_{\mathrm{gen}})&=e_\rho(T).\label{eq:Etor}
\end{align}
Here $M_{\mathrm{gen}}$ denotes a general complex fiber of the parameter curve, and the right-hand sides are nonnegative.

\label{def:exceptional-arrangement}
For a finite full-dimensional toric module $N$, its \emph{exceptional arrangement} is
\begin{equation}\label{eq:exceptional}
\mathcal Z(N)=\overline{\bigcup_{q<d}\deg H^q_{\mathfrak m}(N)}
=-\operatorname{qdeg}\bigoplus_{q<d}\operatorname{Ext}_P^{n-q}(N,\omega_P),
\quad \omega_P=P(\varepsilon_A).
\end{equation}
Here $\operatorname{qdeg}$ denotes the Zariski closure of the set of degrees of nonzero homogeneous elements, and the overline has the same meaning.

\label{def:partial-saturation}
The \emph{partial saturation} of $S_A$ along $a_n$ is the ring
\begin{equation}\label{eq:S-n}
N=S_A^{\{n\}}=\mathbb C[(\mathbb N A+\mathbb Z a_n)\cap\mathbb R_{\geq0}A].
\end{equation}

\label{thm:counterexample}
For every integer $K\geq4$, let
\begin{equation}\label{eq:AK}
A_K=\begin{pmatrix}
1&1&1&1&3&3&2&0\\
0&1&3&4&0&12&4&0\\
0&0&0&0&0&0&1&K
\end{pmatrix},\quad Y=\{x_8=0\}.
\end{equation}
Then $\mathbb Z A_K=\mathbb Z^3$, the cone is pointed, and $S_{A_K}^{\{8\}}=S_{A_K}$ has depth $2$ and dimension $3$. Nevertheless, for every $\beta\in\mathbb C^3$,
\begin{equation}\label{eq:constant-irreg}
d_s(A_K,\beta)=
\begin{cases}
0,&1<s<K/3,\\
36,&s\geq K/3.
\end{cases}
\end{equation}
The only slope along $Y$ is $K/3>1$. The canonical exceptional arrangement is the nonempty union
\begin{equation}\label{eq:ZK}
\mathcal Z(S_{A_K})=
\bigcup_{j=0}^{K-1}\{(1+2j,2+4j,z):z\in\mathbb C\}.
\end{equation}
Thus the reverse inclusion in Proposition~\ref{prop:ext-inclusion}, the equality with the full exceptional arrangement defined by Ext, and the converse to the Cohen--Macaulay implication are false, even at levels above the last slope.

\label{prop:CM-cover}
Let $N$ be a finite full-dimensional Cohen--Macaulay toric module containing $S_A$, and assume that $Q=N/S_A$ has smaller dimension. Then, at every level and parameter,
\begin{equation}\label{eq:CM-defect}
d_s(A,\beta)-d_s(A)
=d_s(H_1(Q,\beta))-d_s(H_0(Q,\beta)).
\end{equation}
The same formula holds for the generic dimension of an individual graded piece. By contrast, for a specialization along a parameter curve, the difference between the fiber values is the single nonnegative term in \eqref{eq:Gtor} or \eqref{eq:Etor}.
